const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

const input = $input.first().json;

/**
 * Formats ISK values
 */
function formatISK(value) {
    if (value === null || value === undefined || isNaN(value)) return '0 ISK';
    if (value >= 1000000000000) return `${(value / 1000000000000).toFixed(1)}T ISK`;
    if (value >= 1000000000) return `${(value / 1000000000).toFixed(1)}B ISK`;
    if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M ISK`;
    if (value >= 1000) return `${(value / 1000).toFixed(0)}K ISK`;
    return `${Math.round(value).toLocaleString()} ISK`;
}

/**
 * Resolves WH static codes to human-readable format
 * @param {Array} staticCodes - Array like ['D845', 'H296']
 * @returns {string} - Formatted like "D845 (High-Sec), H296 (C5)"
 */
async function resolveWormholeStatics(staticCodes) {
    if (!staticCodes || staticCodes.length === 0) return 'None';

    try {
        // Fetch specific WH type definitions using HMGET for efficiency
        const whTypeDataRaw = await redis.hmget('eve:wormhole_types', ...staticCodes);

        if (!whTypeDataRaw || whTypeDataRaw.every(d => d === null)) {
            console.warn('⚠️ No wormhole type data found for codes:', staticCodes);
            return staticCodes.join(', '); // Fallback to just codes
        }

        // Parse and resolve each static code
        const resolved = staticCodes.map((code, index) => {
            const jsonData = whTypeDataRaw[index];
            if (jsonData) {
                try {
                    const whData = JSON.parse(jsonData);
                    if (whData && whData.destination) {
                        return `${code} (→ ${whData.destination})`;
                    }
                } catch (e) {
                    console.warn(`Failed to parse WH type data for ${code}`);
                }
            }
            return code; // If not found, just return the code
        });

        return resolved.join(', ');

    } catch (error) {
        console.error('Error resolving WH statics:', error.message);
        return staticCodes.join(', '); // Fallback
    }
}

// Main report object
let final_report = {
    query: {
        type: input.query_type,
        name: input.query_name
    },
    metadata: {
        generated_at: new Date().toISOString(),
        data_sources: ["SDE", "ESI", "Live Killmails", "Wormhole Database"]
    },
    report: {},
    templated_response_data: {}
};

// --- SYSTEM QUERY LOGIC ---
if (input.query_type === 'system') {
    const sde = input.sde_profile;
    const live = input.esi_live_stats;
    const intel = input.resolved_intel;

    const kills_1h = intel?.resolved_killmails_1h?.length || 0;
    const kills_24h = intel?.resolved_killmails_24h?.length || 0;

    const value_destroyed_1h = intel?.resolved_killmails_1h?.reduce((sum, kill) => sum + (kill.total_value || 0), 0) || 0;
    const value_destroyed_24h = intel?.resolved_killmails_24h?.reduce((sum, kill) => sum + (kill.total_value || 0), 0) || 0;

    const jumps_1h = live?.activity_last_hour?.ship_jumps || 0;
    const npc_kills_1h = live?.activity_last_hour?.npc_kills || 0;

    let threat_level = 'minimal';
    if (kills_1h > 2 || kills_24h > 20) threat_level = 'high';
    else if (kills_1h > 0 || kills_24h > 5) threat_level = 'medium';
    else if (kills_24h > 0) threat_level = 'low';

    const topAttackerChars1h = {};
    if (intel?.resolved_killmails_1h) {
        for (const kill of intel.resolved_killmails_1h) {
            if (kill.attacker_character_name) {
                topAttackerChars1h[kill.attacker_character_name] = (topAttackerChars1h[kill.attacker_character_name] || 0) + 1;
            }
        }
    }
    const sortedAttackerChars1h = Object.entries(topAttackerChars1h)
        .sort((a,b) => b[1] - a[1])
        .slice(0, 3)
        .map(([name]) => name);

    const mostValuableKill24h = intel?.resolved_killmails_24h && intel.resolved_killmails_24h.length > 0
        ? intel.resolved_killmails_24h.sort((a,b) => (b.total_value || 0) - (a.total_value || 0))[0]
        : null;

    // --- ENHANCED WORMHOLE CLASSIFICATION ---
    const whData = sde?.wormhole_data;
    let whClassRaw = whData?.class;
    let whClass = String(whClassRaw);

    let classLabel = '';
    let systemTypeLabel = '';

    if (sde?.security_class === 'wormhole' && whData) {
        // Special wormhole systems
        if (whClass === '12') {
            classLabel = 'C12 (THERA)';
            systemTypeLabel = 'THERA - SPECIAL WORMHOLE SYSTEM';
        } else if (whClass === '13') {
            classLabel = 'C13 (DRIFTER)';
            systemTypeLabel = 'DRIFTER WORMHOLE SYSTEM';
        } else if (whClass.match(/^[1-6]$/)) {
            classLabel = `C${whClass}`;
            systemTypeLabel = `CLASS ${whClass} WORMHOLE`;
        } else if (whClass === 'N/A' || whClass === '0') {
            classLabel = 'UNKNOWN';
            systemTypeLabel = 'J-SPACE SYSTEM (UNCLASSIFIED)';
        } else {
            classLabel = `C${whClass}`;
            systemTypeLabel = `CLASS ${whClass} WORMHOLE`;
        }

        // Add shattered indication if present in effects
        if (whData.effect && whData.effect.toLowerCase().includes('shattered')) {
            systemTypeLabel += ' (SHATTERED)';
        }
    } else if (sde?.security_class !== 'wormhole') {
        // K-space systems
        let sec_status = sde?.security_status || 0.0;
        if (sec_status >= 0.5) {
            systemTypeLabel = "HIGH-SEC SYSTEM";
        } else if (sec_status > 0.0) {
            systemTypeLabel = "LOW-SEC SYSTEM";
        } else {
            let sov_name = sde?.sovereignty?.alliance_name;
            if (sov_name) {
                systemTypeLabel = `NULL-SEC SYSTEM (${sov_name})`;
            } else {
                systemTypeLabel = "NULL-SEC SYSTEM (UNCLAIMED)";
            }
        }
    } else {
        systemTypeLabel = 'UNKNOWN SPACE';
    }

    // --- RESOLVE WORMHOLE STATICS ---
    const staticsList = whData?.statics || [];
    const resolvedStatics = await resolveWormholeStatics(staticsList);

    // --- ASSEMBLE TEMPLATED DATA ---
    final_report.templated_response_data = {
        type: 'system_snapshot',
        query_name: sde?.name || input.query_name,
        security_class: sde?.security_class || 'N/A',
        threat_level: threat_level,
        full_location: sde?.region_name && sde?.constellation_name && sde?.name
            ? `${sde.region_name} > ${sde.constellation_name} > ${sde.name}`
            : (sde?.name || input.query_name),

        last_hour_ship_kills: kills_1h,
        last_hour_npc_kills: npc_kills_1h,
        last_hour_jumps: jumps_1h,

        kills_last_24h: kills_24h,
        value_destroyed_24h_isk: value_destroyed_24h,

        last_hour_killmails_count: kills_1h,
        last_hour_isk_destroyed_formatted: formatISK(value_destroyed_1h),

        most_recent_kill_summary: (intel?.resolved_killmails_1h && intel.resolved_killmails_1h.length > 0)
            ? `${intel.resolved_killmails_1h[0].victim_ship_name || 'Ship'} (${formatISK(intel.resolved_killmails_1h[0].total_value)}) by ${intel.resolved_killmails_1h[0].attacker_character_name || 'Attacker'}`
            : 'No recent kills',

        recent_victim_ships_summary: intel?.hunter_analysis?.top_victim_ships?.map(v => v.name).join(', ') || 'None',
        recent_attacker_chars_summary: sortedAttackerChars1h.length > 0 ? sortedAttackerChars1h.join(', ') : 'None',

        stations: sde?.infrastructure?.stations || 0,
        stargates: sde?.infrastructure?.stargates || 0,

        system_type_label: systemTypeLabel,
        wormhole_class: classLabel || whData?.class || 'N/A',
        wormhole_class_numeric: whData?.class || 0,
        wormhole_effects: whData?.effect || 'None',
        wormhole_statics_list: resolvedStatics,
        wormhole_statics_raw: staticsList,
        wormhole_verified: whData?.verified || false,
        wormhole_data_source: whData?.source || 'N/A',

        static_threat_npc: whData?.threatType || (sde?.security_class === 'wormhole' ? 'Sleeper NPCs' : 'None'),

        top_hunters_24h_list: intel?.hunter_analysis?.top_hunter_corps?.map(h => `${h.name} (${h.count})`).join(', ') || 'None',
        top_victims_24h_list: intel?.hunter_analysis?.top_victim_ships?.map(v => `${v.name} (${v.count})`).join(', ') || 'None',
        value_destroyed_24h_isk_formatted: formatISK(value_destroyed_24h),

        most_valuable_kill_24h_summary: mostValuableKill24h
            ? `${mostValuableKill24h.victim_ship_name || 'Ship'} (${formatISK(mostValuableKill24h.total_value)}) by ${mostValuableKill24h.attacker_character_name || 'Attacker'}`
            : 'None',
    };

    final_report.report = {
        type: 'SystemProfile',
        executive_summary: {
            name: sde?.name || input.query_name,
            id: sde?.id || null,
            full_location: sde?.region_name && sde?.constellation_name && sde?.name
                ? `${sde.region_name} > ${sde.constellation_name} > ${sde.name}`
                : (sde?.name || input.query_name),
            security_class: sde?.security_class || 'N/A',
            sovereignty: sde?.sovereignty?.alliance_name || 'Unclaimed',
            threat_level: threat_level,
            wormhole_info: whData || null,
        },
        threat_intelligence: {
            kills_last_1h: kills_1h,
            kills_last_24h: kills_24h,
            value_destroyed_24h_isk: value_destroyed_24h,
            top_hunters: intel?.hunter_analysis || {},
        },
        static_profile: { ...sde },
    };
}
else if (input.query_type === 'region') {
    const region = input.region_profile;
    const live = input.esi_live_stats;
    const intel = input.resolved_intel;

    const kills_1h = intel?.resolved_killmails_1h?.length || 0;
    const kills_24h = intel?.resolved_killmails_24h?.length || 0;

    const value_destroyed_24h = intel?.resolved_killmails_24h?.reduce((sum, k) => sum + (k.total_value || 0), 0) || 0;
    const value_destroyed_1h = intel?.resolved_killmails_1h?.reduce((sum, k) => sum + (k.total_value || 0), 0) || 0;

    let threat_level = 'minimal';
    if (region?.total_systems > 0 && (kills_24h / region.total_systems > 2)) threat_level = 'high';
    else if (region?.total_systems > 0 && (kills_24h / region.total_systems > 0.5)) threat_level = 'medium';
    else if (kills_24h > 0) threat_level = 'low';

    const mostValuableKill24h = intel?.resolved_killmails_24h?.sort((a,b) => (b.total_value || 0) - (a.total_value || 0))[0] || null;

    final_report.templated_response_data = {
        type: 'region_snapshot',
        query_name: region?.name || input.query_name,
        system_count: region?.total_systems || 0,
        threat_level: threat_level,
        last_hour_jumps: live?.total_jumps || 0,
        last_hour_ship_kills: kills_1h,
        last_hour_npc_kills: live?.total_npc_kills || 0,
        last_hour_killmails_count: kills_1h,
        last_hour_isk_destroyed_formatted: formatISK(value_destroyed_1h),
        top_active_systems_list: live?.top_5_active_systems?.map(s => `${s.name} (${s.score})`).join(', ') || 'None',
        top_regional_hunters_24h_list: intel?.hunter_analysis?.top_hunter_corps?.map(h => `${h.name} (${h.count})`).join(', ') || 'None',
        top_victims_24h_list: intel?.hunter_analysis?.top_victim_ships?.map(v => `${v.name} (${v.count})`).join(', ') || 'None',
        value_destroyed_24h_isk_formatted: formatISK(value_destroyed_24h),
        most_valuable_kill_24h_summary: mostValuableKill24h
            ? `${mostValuableKill24h.victim_ship_name || 'Ship'} (${formatISK(mostValuableKill24h.total_value)}) in ${mostValuableKill24h.system_name || 'N/A'}`
            : 'None',
        kills_last_24h: kills_24h,
        value_destroyed_24h_isk: value_destroyed_24h,
    };

    final_report.report = {
        type: 'RegionProfile',
        executive_summary: {
            name: region?.name || input.query_name,
            id: region?.id || null,
            system_count: region?.total_systems || 0,
            threat_level: threat_level
        },
        threat_intelligence: {
            kills_last_1h: kills_1h,
            kills_last_24h: kills_24h,
            value_destroyed_24h_isk: value_destroyed_24h,
            top_regional_hunters: intel?.hunter_analysis || {},
            hottest_systems_by_activity: live?.top_5_active_systems || []
        },
    };
}

// Cleanup Redis connection
if (redis) {
    try {
        await redis.quit();
    } catch (e) {
        redis.disconnect();
    }
}

return [{ json: { ...input, ...final_report } }];

// Enrich Killmails & Analyze - v2.0 OPTIMIZED
// Uses hmget instead of hgetall for faster name resolution.
// Added checks for input data and improved error logging.
const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

try {
 const input = $input.first().json;
 // --- Input Validation ---
 if (!input) {
  throw new Error("Input data is missing entirely.");
 }
 if (!input.live_intel || !input.live_intel.killmails_1h || !input.live_intel.killmails_24h) {
  console.warn("⚠️ Required live_intel data (killmails_1h or killmails_24h) not found in input. Proceeding with empty lists.", input);
  input.live_intel = input.live_intel || {};
  input.live_intel.killmails_1h = input.live_intel.killmails_1h || [];
  input.live_intel.killmails_24h = input.live_intel.killmails_24h || [];
 }
 // --- End Input Validation ---

 const killmails_1h_raw = input.live_intel.killmails_1h;
 const killmails_24h_raw = input.live_intel.killmails_24h;

 // FIX: EMOJI ENCLOSED
 console.log(`🔍 Processing ${killmails_24h_raw.length} killmails for analysis`);

 // --- STEP 1: Collect all unique IDs needed for name resolution ---
 const idsToResolve = new Set();
 const allKillmailsRaw = [...killmails_1h_raw, ...killmails_24h_raw]; // Combine lists to avoid duplicate lookups

 for (const kill of allKillmailsRaw) {
  if (!kill) continue; // Skip null/undefined killmails

  // System ID
  idsToResolve.add(kill.solar_system_id || kill.system_id);

  // Victim IDs
  if (kill.victim) {
   idsToResolve.add(kill.victim.ship_type_id);
   idsToResolve.add(kill.victim.corporation_id);
   idsToResolve.add(kill.victim.alliance_id);
   idsToResolve.add(kill.victim.character_id);
  }

  // Attacker IDs (check all attackers, not just final blow, for completeness if needed later)
  if (kill.attackers && Array.isArray(kill.attackers)) {
   for (const attacker of kill.attackers) {
    idsToResolve.add(attacker.corporation_id);
    idsToResolve.add(attacker.alliance_id);
    idsToResolve.add(attacker.character_id);
    idsToResolve.add(attacker.ship_type_id);
    idsToResolve.add(attacker.weapon_type_id);
   }
  }
 }
 // Remove null/undefined/0 from the set as they are invalid IDs
 idsToResolve.delete(null);
 idsToResolve.delete(undefined);
 idsToResolve.delete(0);

 const uniqueIdsArray = Array.from(idsToResolve).map(String); // Convert to array of strings for hmget

 // FIX: EMOJI ENCLOSED
 console.log(`🗺️ Need to resolve names for ${uniqueIdsArray.length} unique IDs.`);

 // --- STEP 2: Fetch only the required names using HMGET ---
 let resolvedNamesMap = new Map();
 if (uniqueIdsArray.length > 0) {
  const namesArray = await redis.hmget('eve:id_to_name', ...uniqueIdsArray);

  uniqueIdsArray.forEach((id, index) => {
   if (namesArray[index]) { // Only add if a name was found
    resolvedNamesMap.set(id, namesArray[index]);
   }
  });
  // FIX: EMOJI ENCLOSED
  console.log(`🗺️ Successfully fetched ${resolvedNamesMap.size} names using hmget.`);
 } else {
  // FIX: EMOJI ENCLOSED
  console.log(`🤷 No valid IDs found in killmails to resolve names for.`);
 }

 // --- STEP 3: Define Helper Functions ---
 const getName = (id) => {
  if (!id) return null;
  return resolvedNamesMap.get(String(id)) || null; // Return null explicitly if not found
 };

 const getIskValue = (kill) => {
  if (!kill) return 0; 
  const possibleValues = [
   kill.total_value, // Primary expected field
   kill.zkb?.totalValue, // Common alternative
   kill.zkb?.total_value,
   kill.totalValue, 
   kill.value,
   kill.isk_value
  ];
  for (const value of possibleValues) {
   if (typeof value === 'number' && !isNaN(value) && value > 0) { 
    return value;
   }
  }
  return 0; 
 };

 const enrichKillmail = (kill) => {
  if (!kill) return null; 

  const enrichedKm = { 
   killmail_id: kill.killmail_id, 
   killmail_time: kill.killmail_time || kill.time || kill.killTime,
   total_value: getIskValue(kill), 
   system_id: kill.solar_system_id || kill.system_id, 
   system_name: getName(kill.solar_system_id || kill.system_id) 
  };

  if (kill.victim) {
   enrichedKm.victim_ship_id = kill.victim.ship_type_id;
   enrichedKm.victim_ship_name = getName(kill.victim.ship_type_id);
   enrichedKm.victim_corp_id = kill.victim.corporation_id;
   enrichedKm.victim_corp_name = getName(kill.victim.corporation_id);
   enrichedKm.victim_alliance_id = kill.victim.alliance_id;
   enrichedKm.victim_alliance_name = getName(kill.victim.alliance_id);
   enrichedKm.victim_character_id = kill.victim.character_id;
   enrichedKm.victim_character_name = getName(kill.victim.character_id);
  } else {
   // console.warn(`⚠️ Killmail ${enrichedKm.killmail_id} is missing victim block.`); // Optional: Reduce logging
  }

  const finalBlowAttacker = kill.attackers?.find(a => a.final_blow);
  if (finalBlowAttacker) {
   enrichedKm.attacker_corp_id = finalBlowAttacker.corporation_id;
   enrichedKm.attacker_corp_name = getName(finalBlowAttacker.corporation_id);
   enrichedKm.attacker_alliance_id = finalBlowAttacker.alliance_id;
   enrichedKm.attacker_alliance_name = getName(finalBlowAttacker.alliance_id);
   enrichedKm.attacker_character_id = finalBlowAttacker.character_id;
   enrichedKm.attacker_character_name = getName(finalBlowAttacker.character_id);
   enrichedKm.attacker_ship_id = finalBlowAttacker.ship_type_id;
   enrichedKm.attacker_ship_name = getName(finalBlowAttacker.ship_type_id);
   enrichedKm.attacker_weapon_id = finalBlowAttacker.weapon_type_id;
   enrichedKm.attacker_weapon_name = getName(finalBlowAttacker.weapon_type_id);
  } else {
   // Optional: Reduce logging
   // if (kill.attackers && kill.attackers.length > 0) { console.warn(`⚠️ Killmail ${enrichedKm.killmail_id} has attackers but no final_blow attacker.`); } 
   // else if (!kill.attackers) { console.warn(`⚠️ Killmail ${enrichedKm.killmail_id} is missing attackers block entirely.`); }
  }

  return enrichedKm;
 };

 // --- STEP 4: Enrich Killmails ---
 const enriched_1h = killmails_1h_raw.map(enrichKillmail).filter(km => km !== null);
 const enriched_24h = killmails_24h_raw.map(enrichKillmail).filter(km => km !== null);

 // FIX: EMOJI ENCLOSED
 console.log(`✅ Enriched ${enriched_1h.length} (1h) and ${enriched_24h.length} (24h) killmails successfully.`);

 // --- STEP 5: Calculate ISK & Analyze Hunters ---
 const total1hIsk = enriched_1h.reduce((sum, k) => sum + k.total_value, 0);
 const total24hIsk = enriched_24h.reduce((sum, k) => sum + k.total_value, 0);

 // FIX: EMOJI ENCLOSED
 console.log(`💰 Calculated Total ISK Destroyed - 1h: ${total1hIsk.toLocaleString()}, 24h: ${total24hIsk.toLocaleString()}`);

 const hunter_analysis = {
  top_hunter_corps: {}, top_hunter_alliances: {},
  top_hunter_ships: {}, top_victim_ships: {}
 };

 const aggregate = (map, key) => {
  if (key) { map[key] = (map[key] || 0) + 1; }
 };

 for (const kill of enriched_24h) {
  aggregate(hunter_analysis.top_hunter_corps, kill.attacker_corp_name);
  aggregate(hunter_analysis.top_hunter_alliances, kill.attacker_alliance_name);
  aggregate(hunter_analysis.top_hunter_ships, kill.attacker_ship_name);
  aggregate(hunter_analysis.top_victim_ships, kill.victim_ship_name);
 }

 const toSortedArray = (obj) => Object.entries(obj)
  .sort(([, countA], [, countB]) => countB - countA)
  .map(([name, count]) => ({ name, count }));

 hunter_analysis.top_hunter_corps = toSortedArray(hunter_analysis.top_hunter_corps).slice(0, 5);
 hunter_analysis.top_hunter_alliances = toSortedArray(hunter_analysis.top_hunter_alliances).slice(0, 5);
 hunter_analysis.top_hunter_ships = toSortedArray(hunter_analysis.top_hunter_ships).slice(0, 10);
 hunter_analysis.top_victim_ships = toSortedArray(hunter_analysis.top_victim_ships).slice(0, 10);

 // FIX: EMOJI ENCLOSED
 console.log(`📊 Generated hunter analysis.`);

 const mostValuableKill = enriched_24h.length > 0 
  ? enriched_24h.reduce((maxKill, currentKill) => 
  (currentKill.total_value > maxKill.total_value) ? currentKill : maxKill, enriched_24h[0])
  : null;

 // --- STEP 6: Prepare Final Output ---
 const resolved_intel = {
  resolved_killmails_1h: enriched_1h, 
  resolved_killmails_24h: enriched_24h, 
  hunter_analysis,
  // Optional debug info:
  // debug_info: {
  // total_1h_isk: total1hIsk, total_24h_isk: total24hIsk,
  // most_valuable_kill_isk: mostValuableKill ? mostValuableKill.total_value : 0,
  // ids_resolved_count: resolvedNamesMap.size
  // }
 };

 return [{ json: { ...input, resolved_intel } }];

} catch (error) {
 // FIX: EMOJI ENCLOSED
 console.error(`❌ Enrich Killmails failed: ${error.message}`, error.stack); // Added stack trace
 // Return original input plus a more specific error field
 return [{ json: { ...($input.first()?.json || {}), enrich_error: error.message } }]; 
} finally {
 if (redis) {
  // Using try/catch to ensure robust shutdown on any state
  try {
    if (redis.status === 'ready') {
      await redis.quit();
    } else {
      redis.disconnect(); 
    }
  } catch (e) { 
    // Ignore disconnect errors on shutdown 
  } 
 }
}

// [SYSTEM] Fetch Live Data (Adaptive) - v2.4 (Fixed Time Filtering)
// Reads ESI stats and killmails from Redis keys written by "5. Redis Processing"

const Redis = require('ioredis');
let redis;

try {
	const input = $input.first().json;
	if (!input.system_id) throw new Error(`Missing system_id in input. Did Fetch SDE Profile fail? Input: ${JSON.stringify(input)}`);
	const systemId = parseInt(input.system_id, 10);

	console.log(`Fetching LIVE ESI data for system ID: ${systemId}`);

	redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 }); 

	// --- STEP 1: Fetch LIVE ESI Activity Data (Jumps/Kills) ---
	let liveJumps = 0, liveNpcKills = 0, liveShipKills = 0, livePodKills = 0;

	try {
		const [jumpData, killData] = await Promise.all([
			this.helpers.httpRequest({
				url: 'https://esi.evetech.net/latest/universe/system_jumps/',
				headers: { 'User-Agent': 'EVE-Alfred-Intel/2.4' },
				json: true,
				timeout: 10000
			}),
			this.helpers.httpRequest({
				url: 'https://esi.evetech.net/latest/universe/system_kills/',
				headers: { 'User-Agent': 'EVE-Alfred-Intel/2.4' },
				json: true,
				timeout: 10000
			})
		]);

		const systemJumpData = jumpData.find(s => s.system_id === systemId);
		if (systemJumpData) liveJumps = systemJumpData.ship_jumps || 0;

		const systemKillData = killData.find(s => s.system_id === systemId);
		if (systemKillData) {
			liveNpcKills = systemKillData.npc_kills || 0;
			liveShipKills = systemKillData.ship_kills || 0;
			livePodKills = systemKillData.pod_kills || 0;
		}

		console.log(`✅ LIVE ESI data: ${liveJumps} jumps, ${liveNpcKills} NPC kills, ${liveShipKills} ship kills`);

		redis.hset(`intel:stats:system:${systemId}`, 
			'jumps_1h', liveJumps,
			'npc_kills_1h', liveNpcKills,
			'ship_kills_1h', liveShipKills,
			'pod_kills_1h', livePodKills,
			'last_updated', new Date().toISOString()
		).catch(e => console.warn(`⚠️ Failed to cache live stats: ${e.message}`));

	} catch (esiError) {
		console.warn(`⚠️ ESI fetch failed, falling back to cache: ${esiError.message}`);
		try {
			const cachedStats = await redis.hgetall(`intel:stats:system:${systemId}`);
			if (cachedStats && Object.keys(cachedStats).length > 0) {
				liveJumps = parseInt(cachedStats.jumps_1h || 0, 10);
				liveNpcKills = parseInt(cachedStats.npc_kills_1h || 0, 10);
				liveShipKills = parseInt(cachedStats.ship_kills_1h || 0, 10);
				livePodKills = parseInt(cachedStats.pod_kills_1h || 0, 10);
				console.log(`↪️ Using cached fallback: ${liveJumps}J, ${liveNpcKills}N, ${liveShipKills}S, ${livePodKills}P`);
			} else console.log(`🤷 No cached stats found for ${systemId}.`);
		} catch (cacheError) {
			console.warn(`⚠️ Cache fallback also failed: ${cacheError.message}`);
		}
	}

	// --- STEP 2: Fetch Killmail History from Redis Cache ---
	let recentKills = [];
	try {
		const killKey = `intel:kills:system:${systemId}`; 
		const keyType = await redis.type(killKey);
		console.log(`Kill data key type for ${killKey}: ${keyType}`);

		let killIds = [];
		if (keyType === 'zset') killIds = await redis.zrevrange(killKey, 0, 299);
		else if (keyType === 'list') killIds = await redis.lrange(killKey, 0, 299);
		else if (keyType !== 'none') console.warn(`⚠️ Unexpected key type for kill data: ${keyType}`);

		if (killIds.length > 0) {
			console.log(`Fetching ${killIds.length} killmail details from hash 'intel:kill:data'`);
			const killmailDataRaw = await redis.hmget('intel:kill:data', ...killIds); 
			recentKills = killmailDataRaw.map((k, index) => {
				if (!k) {
					console.warn(`⚠️ Missing killmail data for ID: ${killIds[index]}`);
					return null;
				}
				try { return JSON.parse(k); }
				catch (err) {
					console.warn(`⚠️ Failed to parse killmail ${killIds[index]}: ${err.message}`);
					return null;
				}
			}).filter(Boolean);
		}

	} catch (redisError) {
		console.error(`❌ Redis killmail fetch error: ${redisError.message}`);
	}

	console.log(`Found ${recentKills.length} valid cached killmails for system ${systemId}`);

	// --- STEP 3: Filter Killmails by Time (FIXED) ---
	let live_intel = { killmails_1h: [], killmails_24h: [] };
	if (recentKills.length > 0) {
		const now = Math.floor(Date.now() / 1000); // Seconds
		const oneHourAgo = now - (60 * 60);
		const twentyFourHoursAgo = now - (24 * 60 * 60);

		live_intel.killmails_24h = recentKills.filter(k => {
			const t = k.killmail_time || k.time || k.killTime;
			if (!t) return false;
			try { 
				const killTimeSeconds = Math.floor(new Date(t).getTime() / 1000);
				return killTimeSeconds >= twentyFourHoursAgo;
			}
			catch { return false; }
		});

		live_intel.killmails_1h = live_intel.killmails_24h.filter(k => {
			const t = k.killmail_time || k.time || k.killTime;
			const killTimeSeconds = Math.floor(new Date(t).getTime() / 1000);
			return killTimeSeconds >= oneHourAgo;
		});
	}

	// --- STEP 4: Calculate ISK Totals (FIXED) ---
	const isk_destroyed_1h = live_intel.killmails_1h.reduce((sum, k) => 
		sum + (k.total_value || k.zkb?.totalValue || 0), 0);
	const isk_destroyed_24h = live_intel.killmails_24h.reduce((sum, k) => 
		sum + (k.total_value || k.zkb?.totalValue || 0), 0);

	// --- STEP 5: Assemble Final Report ---
	const esi_live_stats = {
		activity_last_hour: {
			ship_kills: liveShipKills,
			isk_destroyed: isk_destroyed_1h,
			ship_jumps: liveJumps,
			npc_kills: liveNpcKills,
			pod_kills: livePodKills
		},
		activity_last_24h: {
			ship_kills: live_intel.killmails_24h.length,
			isk_destroyed: isk_destroyed_24h
		}
	};

	const output = { 
		...input, 
		esi_live_stats: esi_live_stats, 
		live_intel: live_intel 
	};

	const systemName = input.sde_profile?.name || `ID ${systemId}`;
	console.log(`✅ Live data processed for ${systemName}: ${liveJumps}J, ${liveNpcKills}N, ${liveShipKills}S`);
	return [{ json: output }];

} catch (error) {
	console.error(`❌ Live Data Fetch failed: ${error.message}`);
	return [{ json: { ...($input.first().json || {}), error: `Live Data Fetch failed: ${error.message}` } }];
} finally {
	if (redis) try { await redis.quit(); } catch { redis.disconnect(); }
}

const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

async function processData() {
    let intel;
    try {
        const inputItem = $input.first();
        // Handle case where input might be empty
        const input = inputItem ? inputItem.json : {};

        // --- STEP 0: Robust Input Extraction ---
        // Helper to find a field whether it's in root, body (POST), or query (GET)
        const getField = (key) => {
            if (input[key] !== undefined) return input[key];
            if (input.body && input.body[key] !== undefined) return input.body[key];
            if (input.query && input.query[key] !== undefined) return input.query[key];
            return null;
        };

        const rawQueryName = getField('query_name');

        // Extract and sanitize query name
        const originalQueryName = String(rawQueryName || '').trim(); 
        const queryName = originalQueryName.toLowerCase(); 

        if (!queryName) {
            console.log("Debug - Input received:", JSON.stringify(input)); // Log input for debugging
            throw new Error('Missing query_name. Ensure JSON body contains "query_name".');
        }

        // Ensure these fields exist on the output object for future nodes
        // (This flattens the structure so subsequent nodes don't need to look in .body)
        if (!input.query_name) input.query_name = originalQueryName;
        if (!input.query_type) input.query_type = getField('query_type');

        // --- STEP 1A: System ID Lookup ---
        let systemId;
        const lookupNames = [queryName, originalQueryName, queryName.replace('-', '')];

        for (const name of lookupNames) {
            systemId = await redis.hget('eve:solar_system_name_to_id', name);
            if (systemId) break;
        }

        if (!systemId && /^j\d{6}$/i.test(queryName)) {
            const numeric = parseInt(queryName.match(/\d+/)[0], 10);
            // ✅ FIX: Don't use modulo - J-space IDs can be 6 digits
            systemId = String(31000000 + numeric);
        }

        if (systemId) {
            systemId = String(systemId);
        }

        let isWormhole = (systemId >= 31000000 && systemId < 32000000);
        let systemDetailsFromSDE = false; 
        let system = null;

        // --- STEP 1B: Fetch System Details from Redis ---
        let sysRaw;
        if (systemId) {
            sysRaw = await redis.hget('eve:system_details', systemId);
            if (sysRaw) {
                system = JSON.parse(sysRaw);
                systemDetailsFromSDE = true;
            }
        }

        // --- STEP 2: Minimal stub for J-space if SDE missing ---
        if (isWormhole && !system) {
            system = {
                id: parseInt(systemId),
                name: originalQueryName.toUpperCase(),
                security: -0.99,
                securityClass: 'wormhole'
            };
            systemDetailsFromSDE = false; 
        }

        // --- STEP 3: Fetch Wormhole Data (PRIORITIZE COMPREHENSIVE INDEX) ---
        let wormhole = null;

        if (isWormhole && systemId) {
            // 🔥 CRITICAL FIX: Use eve:wh_system_comprehensive (from hardened Branch 4)
            const whComprehensive = await redis.hget('eve:wh_system_comprehensive', systemId);

            if (whComprehensive) {
                const whData = JSON.parse(whComprehensive);

                wormhole = {
                    class: whData.class,
                    effect: whData.effect || 'None',
                    threatType: whData.threatType || 'Sleeper NPCs',
                    statics: whData.statics || [],
                    verified: whData.verified || false,
                    source: whData.source || 'redis_comprehensive'
                };

                console.log(`✅ Loaded WH data for ${originalQueryName}: C${whData.class}, Statics: ${whData.statics?.join(', ')}`);

            } else {
                // Fallback: try old index structure
                const whRaw = await redis.hget('eve:wh_system_class', systemId);
                const statRaw = await redis.hget('eve:wh_static_connections', systemId);

                if (whRaw) {
                    const whClass = JSON.parse(whRaw);
                    const statics = statRaw ? JSON.parse(statRaw) : null;

                    wormhole = {
                        class: whClass.class || 'N/A',
                        effect: whClass.effect || 'None',
                        threatType: 'Sleeper NPCs',
                        statics: statics?.static_types || [],
                        source: 'redis_legacy'
                    };
                } else {
                    console.warn(`⚠️ No wormhole data found for ${originalQueryName} (${systemId})`);
                    wormhole = {
                        class: 'N/A',
                        effect: 'None',
                        threatType: 'Unknown',
                        statics: [],
                        source: 'missing'
                    };
                }
            }
        }

        // --- STEP 4: Fetch Sovereignty & Infrastructure ---
        const [sovRaw, region, constellation, stations, stargates] = await Promise.all([
            systemId ? redis.hget('eve:sovereignty_map', systemId) : null,
            system?.regionID ? redis.hget('eve:id_to_name', system.regionID) : null,
            system?.constellationID ? redis.hget('eve:id_to_name', system.constellationID) : null,
            systemId ? redis.scard(`eve:stations:system:${systemId}`) : 0,
            systemId ? redis.scard(`eve:stargates:system:${systemId}`) : 0
        ]);

        const sov = sovRaw ? JSON.parse(sovRaw) : null;
        const alliance = sov?.allianceID ? await redis.hget('eve:id_to_name', sov.allianceID) : null;

        // --- STEP 5: Assemble Final Intel Package ---
        intel = {
            system_id: parseInt(systemId),
            name: system?.name || originalQueryName,
            security_status: system?.security,
            security_class: system?.securityClass || (isWormhole ? 'wormhole' : 'unknown'),
            region_id: system?.regionID,
            region_name: region,
            constellation_id: system?.constellationID,
            constellation_name: constellation,
            sovereignty: sov ? { alliance_id: sov.allianceID, alliance_name: alliance } : null,
            wormhole_data: wormhole, // ✅ Now using comprehensive data
            infrastructure: { stations, stargates },
            data_source: systemDetailsFromSDE ? 'redis-sde' : 'esi-fallback'
        };

        return [{ json: { ...input, system_id: intel.system_id, sde_profile: intel, source: intel.data_source } }];

    } catch (error) {
        console.error(`❌ System Intel Tool failed: ${error.message}`);
        // Ensure we handle input safely even in the catch block
        const inputItem = $input.first(); 
        const input = inputItem ? inputItem.json : {};
        return [{ json: { ...input, error: error.message } }];
    } finally {
        if (redis) await redis.quit();
    }
}

return processData();
